r correcting the proven OCR error.", "drive_file_sha256": "c0a099666100482e058b38d6da0c6ef68bfbd143826bd25c61a6dfd557f3667f", "source_page_image_sha256": ["b90f27dd61171b276a9d2352701e25e98ce71cfa3a25ce86af667b4063aa4f65"], "drive_mapping_basis": "Drive and recorded Library PDF have byte-identical embedded question images on this page; PDF wrappers differ."}, "answer_review_status": "source_verified_no_correct_choice"}, "choices": [{"key": "A", "text": "50.7"}, {"key": "B", "text": "15.9"}, {"key": "C", "text": "15.1"}, {"key": "D", "text": "48.2"}]}, {"id": "43f410ac-41a2-a7a0-09b7-effd44fca3ea", "before_hash": "f4408d94db5a9b6212e5d8e7e72b4379", "asset_patch": {"source_recovery_evidence": {"release": "20261005-est-source-evidence", "file_name": "DOC-20260623-WA0016_260916_184619.pdf", "library_file_id": "libfile_e3a383e888208191abcb57b2b4bcde0d", "file_sha256": "0343a54907cd1626fc042f67407ee17914dd0045beeaa0ba9f8c4b807a7512d0", "physical_page": 38, "drive_file_id": null, "mapping_basis": "Exact source_library_path filename and source page; full prompt/choice context visually checked.", "note": "Exact source p38 printed Q18 contains no spinner diagram and states neither equal sector probabilities nor independence. Under those assumptions P(even)=1−(2/4)(2/3)=2/3; absent assumptions leave the probability undetermined. Hold unchanged.", "corroborating_drive_id": "1yl0GXISExsXpdnbEsMUCxXXeUq8R8gNu", "drive_mapping_basis": "Different dated edition; corroboration only, not the exact imported file."}}}, {"id": "492aa09e-a370-8678-c92c-43dbf5eafce1", "before_hash": "e10cd64b5520d8bc47f25adba565e3f1", "asset_patch": {"source_recovery_evidence": {"release": "20261005-est-source-evidence", "file_name": "DOC-20260623-WA0016_260916_184619.pdf", "library_file_id": "libfile_e3a383e888208191abcb57b2b4bcde0d", "file_sha256": "0343a54907cd1626fc042f67407ee17914dd0045beeaa0ba9f8c4b807a7512d0", "physical_page": 43, "drive_file_id": null, "mapping_basis": "Exact source_library_path filename and source page; full prompt/choice context visually checked.", "note": "Exact source p43 printed Q47 calls this a fake die and provides no fairness condition or figure. Four of six labels are prime, giving k=6 only for equally likely faces. Hold unchanged.", "corroborating_drive_id": "1yl0GXISExsXpdnbEsMUCxXXeUq8R8gNu", "drive_mapping_basis": "Different dated edition; corroboration only, not the exact imported file."}}}, {"id": "5a374899-5d5d-d706-1ce4-77197041133e", "before_hash": "25287e9828b5e90878a9c48c9a3a1539", "asset_patch": {"source_recovery_evidence": {"release": "20261005-est-source-evidence", "file_name": "DOC-20260623-WA0016_260916_184619.pdf", "library_file_id": "libfile_e3a383e888208191abcb57b2b4bcde0d", "file_sha256": "0343a54907cd1626fc042f67407ee17914dd0045beeaa0ba9f8c4b807a7512d0", "physical_page": 24, "drive_file_id": null, "mapping_basis": "Exact source_library_path filename and source page; full prompt/choice context visually checked.", "note": "Exact source p24 Q117 reproduces the inconsistent volume units. Formal proportional result 9×26/1.2=195 does not repair the invalid cubic-meter/gallon equivalence. Hold unchanged.", "corroborating_drive_id": "1yl0GXISExsXpdnbEsMUCxXXeUq8R8gNu", "drive_mapping_basis": "Different dated edition; corroboration only, not the exact imported file."}}}, {"id": "92118004-2f60-6326-dab8-e6ad8b7911e7", "before_hash": "767efaa0a8ba49527ddec2af6d03d77c", "asset_patch": {"source_recovery_evidence": {"release": "20261005-est-source-evidence", "file_name": "Revision 1_260823_150138.pdf", "library_file_id": "libfile_ba20da2ba34c8191853fed03ef10e742", "file_sha256": "448ec83d091cc89ab097a9417bcf102b06a196c8a696593d77f1ad404fa54411", "physical_page": 31, "drive_file_id": "1x_wqkBgv1qjLmnbJUThh5jz4-C028zNM", "mapping_basis": "Exact source_library_path filename and source page; full prompt/choice context visually checked.", "note": "Exact source p31 printed Q15 includes A(x)=(2x−3)(2x+3)−(2x²+x−3), with choices 2x²−x−6, 2x²−x+6, 2x²+x−6, 4x²−x−6. Expansion yields A. Restore source text; retain as duplicate of the already verified canonical replacement.", "drive_file_sha256": "c0a099666100482e058b38d6da0c6ef68bfbd143826bd25c61a6dfd557f3667f", "source_page_image_sha256": ["600bcbda09424111efbd6d92187938414f3fbfe0bf0d53ac76db71a27ac88b90", "7657b42b5fecd9ff1f96bb7e49f0df90028a9167f61925673241cd6c256a55e2"], "drive_mapping_basis": "Drive and recorded Library PDF have byte-identical embedded question images on this page; PDF wrappers differ."}, "release_hold_reason": "Duplicate of source-verified canonical question 53c77113-7a68-6837-4af9-b5d4594962cb; source text recovered on 2026-10-05.", "duplicate_of": "53c77113-7a68-6837-4af9-b5d4594962cb", "answer_review_status": "verified_duplicate"}, "stem": "A(x) = (2x − 3)(2x + 3) − (2x² + x − 3). The simplified form of A(x) is:", "choices": [{"key": "A", "text": "2x² − x − 6"}, {"key": "B", "text": "2x² − x + 6"}, {"key": "C", "text": "2x² + x − 6"}, {"key": "D", "text": "4x² − x − 6"}], "explanation": "Expand the difference of squares and subtract the second polynomial: 4x² − 9 − 2x² − x + 3 = 2x² − x − 6, choice A. Verified visually against the exact August p31 printed Q15."}, {"id": "9f479ecd-a687-b0be-fc29-ace016e04fff", "before_hash": "5a4ad45eb4c4deac3761382f52c6b6e0", "asset_patch": {"source_recovery_evidence": {"release": "20261005-est-source-evidence", "file_name": "DOC-20260623-WA0016_260916_184619.pdf", "library_file_id": "libfile_e3a383e888208191abcb57b2b4bcde0d", "file_sha256": "0343a54907cd1626fc042f67407ee17914dd0045beeaa0ba9f8c4b807a7512d0", "physical_page": 20, "drive_file_id": null, "mapping_basis": "Exact source_library_path filename and source page; full prompt/choice context visually checked.", "note": "Exact source p20 Q94 prints 8950.95 with no whole-percent rounding instruction. Implied rate 100((8950.95/6000)^(1/8)−1)=5.1271123…%; 5% yields 8864.73266… . No choice satisfies the exact givens. Hold unchanged.", "corroborating_drive_id": "1yl0GXISExsXpdnbEsMUCxXXeUq8R8gNu", "drive_mapping_basis": "Different dated edition; corroboration only, not the exact imported file."}}}, {"id": "b7c33115-0e83-acfe-d2e7-e5dd4364c922", "before_hash": "9ff859459ab73ecf2205dcaeab6f377e", "asset_patch": {"source_recovery_evidence": {"release": "20261005-est-source-evidence", "file_name": "DOC-20260623-WA0016_260916_184619.pdf", "library_file_id": "libfile_e3a383e888208191abcb57b2b4bcde0d", "file_sha256": "0343a54907cd1626fc042f67407ee17914dd0045beeaa0ba9f8c4b807a7512d0", "physical_page": 38, "drive_file_id": null, "mapping_basis": "Exact source_library_path filename and source page; full prompt/choice context visually checked.", "note": "Exact source p38 printed Q19 does not state independence. Independent trials give 0.3³=0.027; perfectly correlated trials with the same marginal give 0.3. Hold unchanged.", "corroborating_drive_id": "1yl0GXISExsXpdnbEsMUCxXXeUq8R8gNu", "drive_mapping_basis": "Different dated edition; corroboration only, not the exact imported file."}}}, {"id": "c05c0419-86ae-2ebd-9084-98d200f2ac66", "before_hash": "2fbb4368a0568db311cd80b26cb9b4b1", "asset_patch": {"source_recovery_evidence": {"release": "20261005-est-source-evidence", "file_name": "REVISION 2_260630_194855.pdf", "library_file_id": "libfile_ef9f0b1667b48191bd8143933b32d0f3", "file_sha256": "7dc78fdb49a30eeebeb18dcd400d075d649eefb9be15f4d0e7c3d665de4a993d", "physical_page": 23, "drive_file_id": null, "mapping_basis": "Exact source_library_path filename and source page; full prompt/choice context visually checked.", "note": "Exact source p23 printed item 5 has choices 20,200,1150,500. Counting 4 nonzero even hundreds digits ×10 tens digits ×5 odd units gives 200, B, independently confirmed by enumeration. Previously clarified repetition wording and corrected key are preserved; duplicate hold remains.", "drive_mapping_basis": "No exact Drive copy located. Exact original recovered from its recorded Library identity; no substitute Drive mapping asserted."}}}, {"id": "d82839fb-e31c-2d6b-0a23-de7e03d23e35", "before_hash": "ae6f7542446770db1d5742fd1e2fe9d5", "asset_patch": {"source_recovery_evidence": {"release": "20261005-est-source-evidence", "file_name": "REVISION 2_260630_194855.pdf", "library_file_id": "libfile_ef9f0b1667b48191bd8143933b32d0f3", "file_sha256": "7dc78fdb49a30eeebeb18dcd400d075d649eefb9be15f4d0e7c3d665de4a993d", "physical_page": 23, "drive_file_id": null, "mapping_basis": "Exact source_library_path filename and source page; full prompt/choice context visually checked.", "note": "Exact source p23 printed item 1 has all givens and four matching choices. Girls=4550×2/7=1300; without glasses=1300−105=1195, A. Already verified duplicate; preserve duplicate hold and canonical ID.", "drive_mapping_basis": "No exact Drive copy located. Exact original recovered from its recorded Library identity; no substitute Drive mapping asserted."}}}, {"id": "dc220155-bbb4-ddc2-6f65-aa31fc55dd7a", "before_hash": "1fed43ecc767d85166325723f23621cf", "asset_patch": {"source_recovery_evidence": {"release": "20261005-est-source-evidence", "file_name": "REVISION 2_260630_194855.pdf", "library_file_id": "libfile_ef9f0b1667b48191bd8143933b32d0f3", "file_sha256": "7dc78fdb49a30eeebeb18dcd400d075d649eefb9be15f4d0e7c3d665de4a993d", "physical_page": 14, "drive_file_id": null, "mapping_basis": "Exact source_library_path filename and source page; full prompt/choice context visually checked.", "note": "Exact source p14 printed item 8 visibly asks for y² with choices 44.44,6.667,25,9. The handwritten calculations are annotations, not choice text. xy=20, y²=400/9. The source does not specify rounding; A is approximate only. Restore exponent/choices, retain a source-rounding hold and the explicit-rounding adaptation.", "drive_mapping_basis": "No exact Drive copy located. Exact original recovered from its recorded Library identity; no substitute Drive mapping asserted."}, "release_hold_reason": "Source exponent and choices recovered. Exact y² = 400/9; printed 44.44 is approximate and the source omits a rounding instruction. Keep the explicit-rounding adaptation in assessments.", "answer_review_status": "source_verified_rounding_hold"}, "stem": "X and Y are inversely proportional. When x = 4, y = 5. What is the value of y² when x = 3? (Calculator)", "choices": [{"key": "A", "text": "44.44"}, {"key": "B", "text": "6.667"}, {"key": "C", "text": "25"}, {"key": "D", "text": "9"}], "explanation": "Inverse proportion gives xy = 4×5 = 20. At x = 3, y = 20/3, so y² = 400/9 = 44.444… . Printed choice A, 44.44, is an approximation. The exact source does not state a rounding rule; retain the hold and use the separately authored explicit-rounding adaptation."}, {"id": "efd7a835-6f42-cb9a-1a06-07232cdab400", "before_hash": "490279da803a77dad9f10aebd3a57e13", "asset_patch": {"source_recovery_evidence": {"release": "20261005-est-source-evidence", "file_name": "DOC-20260623-WA0016_260916_184619.pdf", "library_file_id": "libfile_e3a383e888208191abcb57b2b4bcde0d", "file_sha256": "0343a54907cd1626fc042f67407ee17914dd0045beeaa0ba9f8c4b807a7512d0", "physical_page": 22, "drive_file_id": null, "mapping_basis": "Exact source_library_path filename and source page; full prompt/choice context visually checked.", "note": "Exact source p22 Q106 has choices 50.7,15.9,15.1,48.2. Weighted total 970; new mean 910/57=15.964912… . None matches; 15.9 is not correct rounding to one decimal. Hold unchanged.", "corroborating_drive_id": "1yl0GXISExsXpdnbEsMUCxXXeUq8R8gNu", "drive_mapping_basis": "Different dated edition; corroboration only, not the exact imported file."}}}]'::jsonb) loop
  select * into strict q from questions where id=(p->>'id')::uuid for update;
  select * into strict k from question_keys where question_id=q.id for update;
  h:=md5(jsonb_build_array(q.stem,q.choices,q.assets,k.correct,k.explanation)::text);
  if h<>p->>'before_hash' then raise exception 'Concurrent content change %',q.id;end if;
  if q.track_id<>'est' or nullif(q.assets->>'release_hold_reason','') is null then raise exception 'Expected held EST original %',q.id;end if;
  before_:=jsonb_build_object('question',to_jsonb(q),'key',to_jsonb(k));
  update questions set stem=coalesce(p->>'stem',stem),choices=coalesce(p->'choices',choices),assets=assets||(p->'asset_patch') where id=q.id;
  if p ? 'explanation' then update question_keys set explanation=p->>'explanation' where question_id=q.id;end if;
  select jsonb_build_object('question',to_jsonb(qq),'key',to_jsonb(kk)) into after_ from questions qq join question_keys kk on kk.question_id=qq.id where qq.id=q.id;
  insert into audit_log(actor_id,action,target_type,target_id,meta) values(null,'question.est_source_evidence_20261005','questions',q.id::text,jsonb_build_object('before',before_,'after',after_));
 end loop;
 select jsonb_build_object('exams',(select md5(coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]')::text) from exams x),'assignments',(select md5(coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]')::text) from assignments x),'attempts',(select md5(coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]')::text) from attempts x),'answers',(select md5(coalesce(jsonb_agg(to_jsonb(x) order by x.attempt_id,x.question_id),'[]')::text) from attempt_answers x),'results',(select md5(coalesce(jsonb_agg(to_jsonb(x) order by x.attempt_id,x.question_id),'[]')::text) from attempt_results x),'revision',(select md5(coalesce(jsonb_agg(to_jsonb(x) order by x.question_id),'[]')::text) from revision_items x)) into protected_after_;
 if protected_before_ is distinct from protected_after_ then raise exception 'Protected assessment, audience, history or revision changed';end if;
end $recovery$;
